module tb;
  reg clk=0, rst=0, data=0;
  wire flag;
  TopModule dut(.clk(clk), .rst(rst), .data(data), .flag(flag));
  always #1 clk = ~clk;

  reg [3:0] hist;
  reg expected;
  integer cycle, errors;
  reg [31:0] stream;

  task step(input bit d);
    begin
      data = d;
      @(posedge clk);
      #0;
      if (cycle >= 4)
        expected = (hist == 4'b1011);
      else
        expected = 0;
      if (flag "'!== expected) begin
        $display("ERR cycle=%0d d=%0b hist=%b state=%0d flag=%0b expected=%0b", cycle, d, hist, dut.state, flag, expected);
        errors = errors + 1;
      end
      hist = {hist[2:0], d};
      cycle = cycle + 1;
    end
  endtask

  integer i, j;
  initial begin
    errors = 0;
    for (i = 0; i < 256; i = i + 1) begin
      rst = 0; data = 0; hist = 0; cycle = 0; expected = 0;
      @(negedge clk); rst = 1;
      stream = i;
      for (j = 7; j >= 0; j = j - 1) begin
        step(stream[j]);
      end
    end
    if (errors == 0) $display("PASS");
    else $display("FAIL errors=%0d", errors);
    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv TopModule.sv tb_check.sv && vvp simv'

